function isBalanced(s) {
  var stack = [];
  var pairs = { ')': '(', ']': '[', '}': '{' };
  for (var i = 0; i < s.length; i++) {
    var ch = s[i];
    if (ch === '(' || ch === '[' || ch === '{') {
      stack.push(ch);
    } else if (ch === ')' || ch === ']' || ch === '}') {
      if (stack.pop() !== pairs[ch]) return false;
    }
  }
  return stack.length === 0;
}

