int max_window_sum(int *a, int n, int k) {
    if (k <= 0 || k > n) return 0;
    int sum = 0;
    for (int i = 0; i < k; i++) sum += a[i];
    int best = sum;
    for (int i = k; i < n; i++) {
        sum += a[i] - a[i - k];
        if (sum > best) best = sum;
    }
    return best;
}

int main() {
    int a[5] = {1, 2, 3, 4, 5};
    printf("%d\n", max_window_sum(a, 5, 2));
    return 0;
}

