solution:
int dedupe(int *a, int n) {
    int w = 0;
    for (int i = 0; i < n; i++) {
        int seen = 0;
        for (int j = 0; j < w; j++) {
            if (a[j] == a[i]) seen = 1;
        }
        if (!seen) {
            a[w] = a[i];
            w++;
        }
    }
    return w;
}

int main() {
    int a[6] = {1, 1, 2, 3, 3, 3};
    printf("%d\n", dedupe(a, 6));
    return 0;
