type Stock = Record<string, number>;

function mergeStock(a: Stock, b: Stock): Stock {
  var out: Stock = {};
  for (var k in a) out[k] = a[k];
  for (var k in b) out[k] = (out[k] || 0) + b[k];
  return out;
}

