function groupByTeam(items) {
  var out = {};
  for (var i = 0; i < items.length; i++) {
    var it = items[i];
    if (it.points < 0) { throw new Error('points 不能为负'); }
    out[it.team] = (out[it.team] || 0) + it.points;
  }
  return out;
}

function topTeam(items) {
  var totals = groupByTeam(items);
  var names = Object.keys(totals);
  if (names.length === 0) { return null; }
  names.sort(function (a, b) {
    if (totals[b] !== totals[a]) { return totals[b] - totals[a]; }
    return a < b ? -1 : (a > b ? 1 : 0);
  });
  return names[0];
}

