function summarize(items: any[]): any {
  var count = items.length;
  var total = 0;
  for (var i = 0; i < count; i++) { total += items[i].value; }
  var average = count === 0 ? 0 : Math.round(total / count * 100) / 100;
  return {count: count, total: total, average: average};
}

function topValue(items: any[]): any {
  if (items.length === 0) { return null; }
  var best = items[0].value;
  for (var i = 1; i < items.length; i++) {
    if (items[i].value > best) { best = items[i].value; }
  }
  return best;
}

